90	void sph_harm_y_all(T theta, T phi, std::tuple<OutMats...> res) {
91	    static constexpr size_t N = sizeof...(OutMats) - 1;
92	
93	    auto &res0 = std::get<0>(res);
94	    int n_max = res0.extent(0) - 1;
95	    int m_max = (res0.extent(1) - 1) / 2;
96	
97	    grad_tuple_t<std::complex<T>, N, 2> res_n_m;
98	    sph_harm_y_for_each_n_m(
99	        n_max, m_max, theta, phi, tuples::ref(res_n_m),
100	        [m_max, res](int n, int m, grad_tuple_t<std::complex<T> &, N, 2> res_n_m) {
101	            if (m >= 0) {
102	                tuples::assign(tuples::submdspan(res, n, m), res_n_m);
103	            } else {
104	                tuples::assign(tuples::submdspan(res, n, m + 2 * m_max + 1), res_n_m);
105	            }
106	        }
107	    );
108	}
